    var solWorld = new GalaxyState { Seed=1, Systems=new[]{sol}, PlanetaryBodies=solBodies, Civilizations=solCivilizations, Fleets=new List<FleetState>(), Colonies=solColonies, Economies=colonySeeder.SeedEconomies(solCivilizations), Technologies=new List<Game.Simulation.Research.TechnologyState>(), ConstructionStates=new ConstructionSeeder().Seed(solCivilizations), ShipyardStates=new List<Game.Simulation.Shipbuilding.ShipyardState>(), PlayerCivilizationId=1, Knowledge=new Game.Simulation.Knowledge.CivilizationKnowledgeState() };
